use std::{fs, hint::black_box as bb, time::Instant};
use serde::Deserialize;
use serde_json::{value::RawValue, Value};
#[derive(Deserialize)] struct Request<P> {jsonrpc:String,method:String,id:Value,params:P}
#[derive(Deserialize)] struct Params {input:Vec<u8>,plugin_id:String,timeout_ms:u64,cpu_cores:f32,memory_bytes:u64,gpu_required:bool,gpu_vram_min_bytes:u64,integrity:Value}
fn consume(p:Params)->usize{bb((p.plugin_id,p.timeout_ms,p.cpu_cores,p.memory_bytes,p.gpu_required,p.gpu_vram_min_bytes,p.integrity));p.input.len()}
fn main(){
 let args:Vec<_>=std::env::args().collect();let input=fs::read(&args[1]).unwrap();let loops:usize=args[2].parse().unwrap();
 for n in 0..6 {for mode in if n%2==0{[0,1]}else{[1,0]}{
  let start=Instant::now();let mut total=0;
  for _ in 0..loops {
   total+=if mode==0 {let req:Request<Value>=serde_json::from_slice(bb(&input)).unwrap();bb((req.jsonrpc,req.method,req.id));consume(serde_json::from_value(req.params).unwrap())}else{let req:Request<&RawValue>=serde_json::from_slice(bb(&input)).unwrap();bb((req.jsonrpc,req.method,req.id));consume(serde_json::from_str(req.params.get()).unwrap())};
  }
  println!("{} {} {} {} {}",n,mode,loops,start.elapsed().as_nanos()/loops as u128,bb(total));
 }}
}
